import _defineProperty from "@babel/runtime/helpers/esm/defineProperty";
import Model from 'flarum/common/Model';

/**
 * A support category (e.g. "Billing", "Appeals"). `isAppeal` categories are
 * the only ones a suspended/banned user may file under.
 */
export default class SupportCategory extends Model {
  constructor() {
    super(...arguments);
    _defineProperty(this, "name", Model.attribute('name'));
    _defineProperty(this, "slug", Model.attribute('slug'));
    _defineProperty(this, "description", Model.attribute('description'));
    _defineProperty(this, "color", Model.attribute('color'));
    _defineProperty(this, "icon", Model.attribute('icon'));
    _defineProperty(this, "position", Model.attribute('position'));
    _defineProperty(this, "isAppeal", Model.attribute('isAppeal'));
    _defineProperty(this, "ticketCount", Model.attribute('ticketCount'));
    _defineProperty(this, "createdAt", Model.attribute('createdAt', Model.transformDate));
    _defineProperty(this, "updatedAt", Model.attribute('updatedAt', Model.transformDate));
  }
}
flarum.reg.add('linkrobins-support', 'common/models/SupportCategory', SupportCategory);